package io.xeros.solo;
import io.xeros.*;import io.xeros.content.bosses.nex.*;import io.xeros.content.bosses.nex.attacks.*;import io.xeros.content.combat.*;import io.xeros.content.combat.death.*;import io.xeros.content.item.lootable.LootRarity;import io.xeros.model.*;import io.xeros.model.definitions.*;import io.xeros.model.entity.npc.*;import io.xeros.model.entity.player.*;import io.xeros.model.entity.player.save.PlayerSave;import io.xeros.model.items.GameItem;import java.lang.reflect.*;import java.util.*;import java.util.function.IntUnaryOperator;
public final class BossesPlayableCheck {
 static void ok(boolean b,String s){if(!b)throw new AssertionError(s);}static Player actor(){Player p=AttackDefencePlayableCheck.actor();p.setIndex(1);p.isActive=true;p.setLoginName("boss63qa");p.setDisplayName("Boss63qa");p.saveCharacter=true;PlayerHandler.players[1]=p;return p;}
 static void tick(int n){SkillsAuditCheck.tick(n);}static void applied(Player p){if(p.getTeleportToX()>0){p.absX=p.getTeleportToX();p.absY=p.getTeleportToY();p.setTeleportToX(-1);p.setTeleportToY(-1);}p.mapRegionX=(p.absX>>3)-6;p.mapRegionY=(p.absY>>3)-6;p.currentX=p.getLocalX();p.currentY=p.getLocalY();}
 static Object field(Object o,String n)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}static void set(Object o,String n,Object v)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);f.set(o,v);}
 static NexNPC enter(Player p){ok(Nex.enterSolo(p),"Nex entry");applied(p);return (NexNPC)p.getInstance().getNpcs().stream().filter(n->n instanceof NexNPC).findFirst().orElseThrow();}
 static void clear(Player p){if(p.getInstance()!=null)p.getInstance().remove(p);SkillsAuditCheck.clear(p);p.setDisconnected(true);PlayerHandler.players[1]=null;tick(16);}
 static int count(Player p,int id){return p.getItems().getInventoryCount(id);}static void give(Player p,int id,int n){ok(p.getItems().addItem(id,n),"Fixture "+id);}
 static void loot(NexNPC n,int item)throws Exception{List<GameItem> rare=NexNPC.getItems().get(LootRarity.RARE);int selected=-1;for(int i=0;i<rare.size();i++)if(rare.get(i).getId()==item){selected=i;break;}ok(selected>=0,"Loot absent "+item);final int index=selected;set(n,"lootRoll",(IntUnaryOperator)(b->b==10?0:index));}
 static void access()throws Exception{
  for(int m=0;m<4;m++){Player p=actor();if(m==0)p.getHealth().setCurrentHealth(0);if(m==1)p.isDead=true;if(m==2)p.isBanking=true;if(m==3)p.teleTimer=3;ok(!Nex.enterSolo(p)&&p.getInstance()==null,"Invalid entry "+m);clear(p);}
  Player p=actor();NexNPC n=enter(p);Nex arena=(Nex)p.getInstance();ok(arena.getPlayers().size()==1&&arena.getNpcs().size()==1&&!Nex.enterSolo(p),"Entry duplicated");ok(PlayerSave.saveGameInstant(p),"Save inside Nex");Player q=AttackDefencePlayableCheck.actor();q.setLoginName("boss63qa");ok(PlayerSave.loadGame(q,"boss63qa","IsolatedAudit",true).toString().equals("SUCCESS")&&q.heightLevel==0&&q.getTeleportToX()==2904&&q.getTeleportToY()==5206,"Relog into abandoned Nex instance");arena.remove(p);applied(p);tick(20);new ArrayList<>(arena.getNpcs()).forEach(NPC::processDeregistration);ok(arena.isDisposed()&&arena.getNpcs().stream().noneMatch(NPC::isRegistered),"Startup spawned after instance exit");clear(p);SkillsAuditCheck.clear(q);
  System.out.println("BOSSES_NEX_ENTRY_GUARDS_SINGLE_INSTANCE_EXIT_STARTUP_CANCEL_AND_INSIDE_INSTANCE_REAL_SAVE_SAFE_RELOAD_PASS");
 }
 static void phases()throws Exception{
  Player p=actor();p.getHealth().setMaximumHealth(5000);p.getHealth().reset();NexNPC n=enter(p);tick(14);n.updateTargets();ok(n.canBeAttacked(p),"Nex never starts");int hp=n.getHealth().getCurrentHealth();n.appendDamage(p,10,Hitmark.HIT);ok(n.getHealth().getCurrentHealth()==hp-10,"Player cannot damage Nex");
  String[] names={"fumusNPC","umbraNPC","cruorNPC","glaciesNPC"},phases={"SHADOW","BLOOD","ICE","ZAROS"};double[] thresholds={.8,.6,.4,.2};
  for(int i=0;i<4;i++){n.getHealth().setCurrentHealth((int)(n.getHealth().getMaximumHealth()*thresholds[i]));n.process();ok(!n.canBeAttacked(p),"Nex not gated "+i);int before=n.getHealth().getCurrentHealth();n.appendDamage(p,100,Hitmark.HIT);ok(n.getHealth().getCurrentHealth()==before,"Damage bypasses minion gate "+i);NPC minion=(NPC)field(n,names[i]);ok(minion!=null&&!minion.isInvisible(),"Minion absent/hidden "+i);minion.appendDamage(p,minion.getHealth().getCurrentHealth(),Hitmark.HIT);n.process();ok(field(n,"currentPhase").toString().equals(phases[i])&&n.canBeAttacked(p),"Nex phase stuck "+i);}
  loot(n,26382);int before=count(p,26382),kc=p.getNpcDeathTracker().getKc("Nex");n.appendDamage(p,n.getHealth().getCurrentHealth(),Hitmark.HIT);for(int i=0;i<40&&count(p,26382)==before;i++){Server.npcHandler.getNpcProcess().process(n.getIndex());tick(1);}ok(count(p,26382)==before+1&&p.getInstance()==null&&p.heightLevel==0,"Real Nex death did not pay Torva and exit");ok(p.getNpcDeathTracker().getKc("Nex")==kc+1,"Nex KC");n.onDeath();n.getReward(p);ok(count(p,26382)==before+1,"Duplicate Nex reward");ok(PlayerSave.saveGameInstant(p),"Victory save");Player q=AttackDefencePlayableCheck.actor();q.setLoginName("boss63qa");ok(PlayerSave.loadGame(q,"boss63qa","IsolatedAudit",true).toString().equals("SUCCESS")&&count(q,26382)==before+1&&q.getTeleportToX()==2904&&q.getTeleportToY()==5206&&q.getNpcDeathTracker().getKc("Nex")==kc+1,"Torva/KC/exit persistence");clear(p);SkillsAuditCheck.clear(q);
  System.out.println("BOSSES_NEX_FIVE_PHASES_FOUR_MINIONS_DAMAGE_GATES_REAL_NPC_DEATH_TORVA_HELM_SINGLE_REWARD_KC_AND_SAVE_RELOAD_PASS");
 }
 static void torva()throws Exception{
  for(int id:new int[]{26382,26384,26386}){Player p=actor();NexNPC n=enter(p);loot(n,id);int initial=count(p,id);n.onDeath();ok(count(p,id)==initial,"Living Nex paid loot");n.getHealth().setCurrentHealth(0);n.setDead(true);n.onDeath();ok(count(p,id)==initial+1&&p.getInstance()==null,"Torva item reward "+id);n.onDeath();n.getReward(p);ok(count(p,id)==initial+1,"Torva duplicate "+id);clear(p);}
  Player p=actor();NexNPC n=enter(p);loot(n,26384);while(p.getItems().freeSlots()>0)give(p,526,1);n.getHealth().setCurrentHealth(0);n.setDead(true);n.onDeath();ok(p.getItems().bankContains(26384)&&count(p,26384)==0,"Full bag reward not banked");clear(p);
  System.out.println("BOSSES_NEX_THREE_TORVA_IDS_NATIVE_DEFINITIONS_SINGLE_REWARD_AND_FULL_INVENTORY_BANK_FALLBACK_PASS");
 }
 static void delayed()throws Exception{
  Player p=actor();NexNPC n=enter(p);Nex arena=(Nex)p.getInstance();int health=p.getHealth().getCurrentHealth();new BloodSacrifice(n,p);new ChokeAttack(p);new IcePrison(List.of(p));arena.remove(p);p.absX=2924;p.absY=5202;p.heightLevel=arena.getHeight();tick(30);ok(p.getHealth().getCurrentHealth()==health&&!p.hasNexVirus,"Old encounter attack hit exited player");clear(p);
  p=actor();p.getHealth().setMaximumHealth(5000);p.getHealth().reset();n=enter(p);int prayer=p.playerLevel[5];p.prayerPoint=.75;new BloodSacrifice(n,p);tick(7);ok(p.playerLevel[5]==(int)Math.floor(prayer*.67)&&p.prayerPoint==.75,"Sacrifice drained fractional clock rather than Prayer");clear(p);
  System.out.println("BOSSES_NEX_DELAYED_HITS_VIRUS_ICE_CANCEL_ON_INSTANCE_EXIT_AND_BLOOD_SACRIFICE_ACTUAL_PRAYER_POINTS_PASS");
 }
 public static void main(String[]a)throws Exception{Thread.setDefaultUncaughtExceptionHandler((t,e)->{e.printStackTrace();System.exit(1);});Thread.currentThread().setName("GameThread");System.setProperty("solo.mode","true");System.setProperty("solo.xp","1");Server.startServerless();Configuration.BONUS_SKILL=-1;access();phases();torva();delayed();System.out.println("BOSSES_NEX_PLAYABLE_V63_PASS");System.exit(0);}
}
